-- Import the existing Porto Moniz catalogue into the shared archipelago directory.
-- Official restaurant entries are source-listed from the municipal restaurant page.
-- Other businesses remain unverified leads until their current operation/contact details are confirmed.

on conflict (id) do update set
  name=excluded.name,category=excluded.category,publisher=excluded.publisher,url=excluded.url,
  authority=excluded.authority,scope=excluded.scope,update_note=excluded.update_note;

update public.island_sources
set last_checked_at=now()
where id='porto-moniz-municipality';

on conflict (external_key) do update set
  name=excluded.name,category=excluded.category,description=excluded.description,
  municipality_id=excluded.municipality_id,parish=excluded.parish,address=excluded.address,
  phone=excluded.phone,website=excluded.website,source_id=excluded.source_id,
  source_url=excluded.source_url,verification_status=excluded.verification_status,
  last_verified_at=excluded.last_verified_at,is_active=excluded.is_active,updated_at=now();
